    collection_name = "collection-" + str(collection_id)
    self.llm = ChatOpenAI(model_name=self.model_name, temperature=self.temperature, openai_api_key=os.environ.get('OPENAI_API_KEY'), streaming=True, callback_manager=CallbackManager())
    self.memory = ConversationBufferMemory(memory_key="chat_history", return_messages=True, output_key='answer')

